import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].unitPrice, 8500);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].qty, 10);
  assert.equal(result.value.lines[1].unitPrice, 9500);
  assert.equal(result.value.lines[1].vatRate, 21);
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports invalid date format', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026/10/07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports invalid date (month out of range)', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports invalid date (day out of range)', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports non-integer quantity', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports zero quantity', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports negative quantity', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports unknown SKU', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 5 }]);
});

test('createInvoice works with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 9);
  assert.equal(result.value.lines[1].vatRate, 0);
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals returns zero for empty invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 2, unitPrice: 120000, name: 'Logo package', vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 240000);
  assert.equal(totals.total, 240000);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
    ],
  };
  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
    ],
  };
  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine rejects non-integer quantity', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
    ],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects non-positive quantity', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
    ],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
    ],
  };
  assert.deepEqual(addLine(invoice, { sku: 'NOPE', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
    ],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate input', () => {
  const lines = [
    { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
  ];
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines,
  };
  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(invoice.lines.length, 1);
  assert.equal(lines[0].qty, 5);
});

test('removeLine removes a line by SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, name: 'Development (hour)', vatRate: 21 },
    ],
  };
  const result = removeLine(invoice, 'DES-HOUR');
